require "rails_helper"
require "json"

# Conformance (formal/INTEGRATION.md, layer 3): formal/fixtures/train_evidence.json
# is TrainEvidence.landed's verdict over every combination of its evidence
# inputs, generated by `lake exe syrus_fixtures train_evidence`. This runs the
# real Steps::MergeTrainLand#member_landed? with the same inputs and compares.
# The leaves (git ancestry, the build-time record, patch equivalence, the
# rebased-integration patch match) are git queries and are stubbed; how they
# combine into "this member landed" is what the model is about.
RSpec.describe "TrainEvidence model conformance" do
  fixture = JSON.parse(Rails.root.join("formal/fixtures/train_evidence.json").read)
  ancestry = { "ancestor" => :ancestor, "not_ancestor" => :not_ancestor, "indeterminate" => :indeterminate }

  let(:job) { Factories.job_record }
  let(:handler) do
    workflow = Workflow.create!(job: job, trigger_kind: "merge_train")
    step = Step.create!(workflow: workflow, kind: "merge_train_land", position: 0)
    Steps::MergeTrainLand.new(Run.create!(job: job, step: step, trigger_kind: "merge_train"))
  end

  it "covers every combination of the evidence inputs" do
    expect(fixture.fetch("cases").size).to eq(2 * 3 * 2 * 2 * 2)
  end

  fixture.fetch("cases").each do |example|
    inputs = example.except("landed")
    it "decides #{inputs.map { |key, value| "#{key}=#{value}" }.join(', ')} as #{example.fetch('landed') ? 'landed' : 'not landed'}" do
      LandedCommit.create!(landable: job, sha: "recorded-sha", kind: "implementation", position: 0) if example.fetch("recorded")
      allow(handler).to receive(:ancestor_of_integration).and_return(ancestry.fetch(example.fetch("ancestry")))
      allow(handler).to receive(:trust_recent_build_evidence?).and_return(example.fetch("recent_build"))
      allow(handler).to receive(:patch_equivalent_on_landed_base?).and_return(example.fetch("patch_equivalent"))
      allow(handler).to receive(:rebased_into_integration?).and_return(example.fetch("rebased_into_integration"))

      expect(handler.send(:member_landed?, job, "integration-sha", train: nil, client: nil)).to eq(example.fetch("landed"))
    end
  end
end
